import operator
import re
import sys

_TOKEN_RE = re.compile(r"<>|<=|>=|[-+*/(),:=<>]|[A-Z]+[0-9]*|[0-9]+")
_CYCLE = "#CYCLE!"
_DIV0 = "#DIV/0!"
_CMP = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    # Evaluation recurses through reference chains, which can span every cell.
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))

    values: dict[str, int | str] = {}
    state: dict[str, int] = {}  # absent: unvisited, 1: in progress, 2: done

    def is_cell(tok: str) -> bool:
        return tok[0].isalpha() and tok[-1].isdigit()

    def parse(text: str) -> tuple:
        toks = _TOKEN_RE.findall(re.sub(r"\s+", "", text))
        pos = 0

        def peek(k: int = 0):
            return toks[pos + k] if pos + k < len(toks) else None

        def take() -> str:
            nonlocal pos
            tok = toks[pos]
            pos += 1
            return tok

        def expr() -> tuple:
            node = term()
            while peek() in ("+", "-"):
                op = take()
                node = ("bin", op, node, term())
            return node

        def term() -> tuple:
            node = unary()
            while peek() in ("*", "/"):
                op = take()
                node = ("bin", op, node, unary())
            return node

        def unary() -> tuple:
            if peek() == "-":
                take()
                return ("neg", unary())
            return atom()

        def atom() -> tuple:
            tok = take()
            if tok == "(":
                node = expr()
                take()  # ')'
                return node
            if tok.isdigit():
                return ("num", int(tok))
            if is_cell(tok):
                return ("ref", tok)
            if tok == "IF":
                take()  # '('
                left = expr()
                op = take()
                right = expr()
                take()  # ','
                then = expr()
                take()  # ','
                other = expr()
                take()  # ')'
                return ("if", op, left, right, then, other)
            # SUM, MIN or MAX
            take()  # '('
            args = []
            while True:
                nxt = peek()
                if nxt is not None and is_cell(nxt) and peek(1) == ":":
                    first = take()
                    take()  # ':'
                    second = take()
                    args.append(("range", first, second))
                else:
                    args.append(("expr", expr()))
                if peek() == ",":
                    take()
                    continue
                break
            take()  # ')'
            return ("call", tok, args)

        return expr()

    def cells_in_range(c1: str, c2: str) -> list[str]:
        col_lo, col_hi = sorted((c1[0], c2[0]))
        row_lo, row_hi = sorted((int(c1[1:]), int(c2[1:])))
        names = []
        for row in range(row_lo, row_hi + 1):  # top row first
            for col_code in range(ord(col_lo), ord(col_hi) + 1):
                name = f"{chr(col_code)}{row}"
                if name in cells:
                    names.append(name)
        return names

    def cell_value(name: str) -> int | str:
        if name not in cells:
            return 0
        s = state.get(name, 0)
        if s == 2:
            return values[name]
        if s == 1:
            return _CYCLE
        state[name] = 1
        content = cells[name].strip()
        if content.startswith("="):
            result = ev(parse(content[1:]))
        else:
            result = int(content)
        values[name] = result
        state[name] = 2
        return result

    def ev(node: tuple) -> int | str:
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return cell_value(node[1])
        if kind == "neg":
            v = ev(node[1])
            return v if isinstance(v, str) else -v
        if kind == "bin":
            a = ev(node[2])
            if isinstance(a, str):
                return a
            b = ev(node[3])
            if isinstance(b, str):
                return b
            op = node[1]
            if op == "+":
                return a + b
            if op == "-":
                return a - b
            if op == "*":
                return a * b
            if b == 0:
                return _DIV0
            # Truncate toward zero.
            q = abs(a) // abs(b)
            return q if (a < 0) == (b < 0) else -q
        if kind == "if":
            _, op, left, right, then, other = node
            a = ev(left)
            if isinstance(a, str):
                return a
            b = ev(right)
            if isinstance(b, str):
                return b
            return ev(then if _CMP[op](a, b) else other)
        # kind == "call"
        name, args = node[1], node[2]
        found = []
        for arg in args:
            if arg[0] == "range":
                for ref in cells_in_range(arg[1], arg[2]):
                    v = cell_value(ref)
                    if isinstance(v, str):
                        return v
                    found.append(v)
            else:
                v = ev(arg[1])
                if isinstance(v, str):
                    return v
                found.append(v)
        if name == "SUM":
            return sum(found)
        if not found:
            return 0
        return min(found) if name == "MIN" else max(found)

    for name in cells:
        cell_value(name)
    return {name: values[name] for name in cells}
